use std::{process::{Command, Child}, time::{Duration, Instant, SystemTime}, thread::sleep, collections::HashSet};
use windows_sys::Win32::{Foundation::*, Graphics::Gdi::*, System::{Diagnostics::ToolHelp::*, ProcessStatus::*, Threading::*}, UI::{HiDpi::*, WindowsAndMessaging::*, Input::KeyboardAndMouse::*}, System::SystemInformation::GetTickCount, System::Power::*};
fn now() -> u128 { SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_micros() }
fn magenta(sc: f64) -> bool { unsafe { let t: Vec<u16> = "bench-window\0".encode_utf16().collect(); let h = FindWindowW(std::ptr::null(), t.as_ptr()); if h.is_null() || IsWindowVisible(h) == 0 { return false; } let mut r: RECT = std::mem::zeroed(); GetWindowRect(h, &mut r); let (x, y) = (r.left + (368.0 * sc) as i32, r.top + (132.0 * sc) as i32); let dc = GetDC(std::ptr::null_mut()); let c = GetPixel(dc, x, y); ReleaseDC(std::ptr::null_mut(), dc); let (r, g, b) = (c & 255, c >> 8 & 255, c >> 16 & 255); r > 180 && g < 110 && b > 180 } }
fn ctime(h: HANDLE) -> (u64, u64) { unsafe { let mut f: [FILETIME; 4] = std::mem::zeroed(); let p = f.as_mut_ptr(); GetProcessTimes(h, p, p.add(1), p.add(2), p.add(3)); let g = |t: FILETIME| (t.dwHighDateTime as u64) << 32 | t.dwLowDateTime as u64; (g(f[0]), g(f[2]) + g(f[3])) } }
struct M { ws_kb: u64, n: usize, priv_kb: u64, pws_kb: u64, cpu_ms: f64, host_priv_kb: u64, wv: usize }
fn tree(root: u32) -> M { unsafe { let sn = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0); let mut e: PROCESSENTRY32W = std::mem::zeroed(); e.dwSize = std::mem::size_of_val(&e) as u32; let mut all = vec![]; let mut ok = Process32FirstW(sn, &mut e);
    while ok != 0 { let n = String::from_utf16_lossy(&e.szExeFile).trim_end_matches('\0').to_lowercase(); all.push((e.th32ProcessID, e.th32ParentProcessID, n)); ok = Process32NextW(sn, &mut e); } CloseHandle(sn);
    let mut set = HashSet::from([root]); loop { let before = set.len(); for (p, pp, _) in &all { if set.contains(pp) && *p != 0 { set.insert(*p); } } if set.len() == before { break; } }
    let mut m = M { ws_kb: 0, n: 0, priv_kb: 0, pws_kb: 0, cpu_ms: 0.0, host_priv_kb: 0, wv: 0 };
    let rh = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, root); let rt = ctime(rh).0; CloseHandle(rh);
    for p in set { let h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, p); if h.is_null() { continue; } let (c, cpu) = ctime(h); if c < rt { CloseHandle(h); continue; }
        let mut pm: PROCESS_MEMORY_COUNTERS_EX2 = std::mem::zeroed(); pm.cb = std::mem::size_of_val(&pm) as u32; K32GetProcessMemoryInfo(h, &mut pm as *mut _ as *mut _, pm.cb); CloseHandle(h);
        m.n += 1; m.ws_kb += pm.WorkingSetSize as u64 / 1024; m.priv_kb += pm.PrivateUsage as u64 / 1024; m.pws_kb += pm.PrivateWorkingSetSize as u64 / 1024; m.cpu_ms += cpu as f64 / 1e4; if p == root { m.host_priv_kb = pm.PrivateUsage as u64 / 1024; }
        if all.iter().any(|a| a.0 == p && a.2.contains("msedgewebview2")) { m.wv += 1; } } m } }
fn note(l: &str) { unsafe { let mut li = LASTINPUTINFO { cbSize: 8, dwTime: 0 }; GetLastInputInfo(&mut li); let mut f: [FILETIME; 3] = std::mem::zeroed(); let p = f.as_mut_ptr(); GetSystemTimes(p, p.add(1), p.add(2)); let g = |t: FILETIME| (t.dwHighDateTime as u64) << 32 | t.dwLowDateTime as u64; let mut ps: SYSTEM_POWER_STATUS = std::mem::zeroed(); GetSystemPowerStatus(&mut ps);
  static mut LAST: (u64, u64) = (0, 0); let (idle, tot) = (g(f[0]), g(f[1]) + g(f[2])); let (li0, lt0) = LAST; LAST = (idle, tot); println!("  [{l}] last_input={}s ago, system_cpu={:.0}%, ac={}", GetTickCount().wrapping_sub(li.dwTime) / 1000, 100.0 - (idle - li0) as f64 * 100.0 / (tot - lt0) as f64, ps.ACLineStatus); } }
fn present(secs: f64) { unsafe { let t: Vec<u16> = "bench-window\0".encode_utf16().collect(); let h = FindWindowW(std::ptr::null(), t.as_ptr()); let mut r: RECT = std::mem::zeroed(); GetClientRect(h, &mut r); let mut o = POINT { x: 0, y: 0 }; ClientToScreen(h, &mut o); let mut top = 0; let fg = GetForegroundWindow() == h; let (w, hh) = (4i32, 500i32);
  let sdc = GetDC(std::ptr::null_mut()); let mdc = CreateCompatibleDC(sdc); let mut bi: BITMAPINFO = std::mem::zeroed(); bi.bmiHeader.biSize = 40; bi.bmiHeader.biWidth = w; bi.bmiHeader.biHeight = -hh; bi.bmiHeader.biPlanes = 1; bi.bmiHeader.biBitCount = 32; let mut bits: *mut core::ffi::c_void = std::ptr::null_mut(); let bmp = CreateDIBSection(mdc, &bi, 0, &mut bits, std::ptr::null_mut(), 0); SelectObject(mdc, bmp as _);
  let (t0, mut last, mut uniq, mut gaps, mut tl) = (Instant::now(), 0u64, 0u32, vec![], Instant::now()); while t0.elapsed().as_secs_f64() < secs { BitBlt(mdc, 0, 0, w, hh, sdc, o.x + r.right / 16, o.y + 40, SRCCOPY); GdiFlush(); top += 1; let d = std::slice::from_raw_parts(bits as *const u32, (w * hh) as usize); let hs = d.iter().fold(1469598103934665603u64, |a, x| (a ^ *x as u64).wrapping_mul(1099511628211)); if hs != last { if last != 0 { gaps.push(tl.elapsed().as_secs_f64() * 1e3); } tl = Instant::now(); last = hs; uniq += 1; } }
  println!("client={}x{} fg={fg} samples/s={:.0} shown_fps={:.1} gap_median={:.2} p95={:.2} p99={:.2} max={:.1}", r.right, r.bottom, top as f64 / secs, uniq as f64 / secs, pct(&mut gaps, 0.5), pct(&mut gaps, 0.95), pct(&mut gaps, 0.99), pct(&mut gaps, 1.0)); } }
fn show(l: &str, m: &M) { println!("{l}: procs={} webview2={} private={:.1}MB privWS={:.1}MB hostPrivate={:.1}MB totalWS={:.1}MB cpu={:.0}ms", m.n, m.wv, m.priv_kb as f64 / 1024., m.pws_kb as f64 / 1024., m.host_priv_kb as f64 / 1024., m.ws_kb as f64 / 1024., m.cpu_ms); }
fn pct(v: &mut Vec<f64>, p: f64) -> f64 { v.sort_by(|a, b| a.partial_cmp(b).unwrap()); if v.is_empty() { return f64::NAN; } v[((v.len() - 1) as f64 * p).round() as usize] }
fn main() { unsafe { SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2); }
    let a: Vec<String> = std::env::args().collect(); let (exe, thumbs, work) = (&a[1], &a[2], &a[3]); let sc = unsafe { GetDpiForSystem() } as f64 / 96.0; 
    let hz = unsafe { let dc = GetDC(std::ptr::null_mut()); let r = GetDeviceCaps(dc, VREFRESH as i32); ReleaseDC(std::ptr::null_mut(), dc); r }; println!("scale={sc} hz={hz} exe={:.2}MB", std::fs::metadata(exe).unwrap().len() as f64 / 1e6);
    let logf = |m: &str| format!("{work}/{m}.log"); let run = |m: &str| -> Child { let _ = std::fs::remove_file(logf(m)); Command::new(exe).args([m, thumbs, &logf(m), &format!("{work}/data")]).spawn().unwrap() };
    let lines = |m: &str| -> Vec<(u128, String)> { std::fs::read_to_string(logf(m)).unwrap_or_default().lines().filter_map(|l| l.split_once(' ').map(|(t, s)| (t.parse().unwrap(), s.into()))).collect() };
    if magenta(sc) { panic!("pixel already magenta") }
    note("begin"); if std::env::var("BENCH_PRESENT").is_ok() { note("b"); let mut c = run("scroll"); sleep(Duration::from_millis(2200)); show("open", &tree(c.id())); sleep(Duration::from_millis(2300)); let a = tree(c.id()); present(6.0); let b = tree(c.id()); show("scroll", &b); println!("scroll cpu over 6s={:.0}ms", b.cpu_ms - a.cpu_ms); note("p"); let _ = c.wait(); return; }
    let only = std::env::var("BENCH_COLS").is_ok(); if only { note("begin"); }
    let mut st = vec![]; for i in 0..if only { 0 } else { 11 } { let t = Instant::now(); let mut c = run("open"); let mut got = f64::NAN; while t.elapsed() < Duration::from_secs(15) { if magenta(sc) { got = t.elapsed().as_secs_f64() * 1e3; break; } sleep(Duration::from_millis(1)); }
        sleep(Duration::from_millis(700)); let _ = c.kill(); let _ = c.wait(); sleep(Duration::from_millis(2500)); if i == 0 { println!("start first={got:.0}ms"); } else { st.push(got); } }
    note("start"); println!("start n={} raw={:?}", st.len(), st.iter().map(|x| x.round()).collect::<Vec<_>>()); println!("start median={:.0} p95={:.0}", pct(&mut st, 0.5), pct(&mut st, 0.95));
    let mut c = run("open"); sleep(Duration::from_secs(12)); let m1 = tree(c.id()); show("open12s", &m1); sleep(Duration::from_secs(4)); let m2 = tree(c.id()); note("open"); println!("open idle cpu over 4s={:.0}ms", m2.cpu_ms - m1.cpu_ms); let _ = c.wait(); sleep(Duration::from_secs(2));
    let mut c = run("scroll"); sleep(Duration::from_millis(5000)); let m1 = tree(c.id()); sleep(Duration::from_secs(6)); let m2 = tree(c.id()); show("scroll", &m2); note("scroll"); println!("scroll cpu over 6s={:.0}ms", m2.cpu_ms - m1.cpu_ms); sleep(Duration::from_secs(4)); show("after_scroll", &tree(c.id())); let _ = c.wait();
    if let Some((_, f)) = lines("scroll").iter().find(|l| l.1.starts_with("frames ")) { let mut v: Vec<f64> = f[7..].split(',').map(|x| x.parse().unwrap()).collect(); let n = v.len(); let b = 1000.0 / hz as f64; let late = v.iter().filter(|x| **x > b * 1.5).count(); println!("frames n={n} median={:.2} p95={:.2} p99={:.2} max={:.2} late(>1.5 interval)={late}", pct(&mut v, 0.5), pct(&mut v, 0.95), pct(&mut v, 0.99), pct(&mut v, 1.0)); } else { println!("frames none"); }
    if only { return; } sleep(Duration::from_secs(2)); let mut c = run("min"); sleep(Duration::from_secs(15)); show("min15s", &tree(c.id())); let _ = c.wait(); sleep(Duration::from_secs(1));
    let mut c = run("tray"); let mut prev = false; let mut vis = vec![]; let (mut d1, mut d2) = (false, false); let mut lastchk = Instant::now();
    loop { if c.try_wait().unwrap().is_some() { break; } let m = magenta(sc); if m && !prev { vis.push(now()); } prev = m;
        if lastchk.elapsed() > Duration::from_millis(500) { lastchk = Instant::now(); let l = lines("tray"); let t = now(); if !d1 { if let Some(x) = l.iter().find(|x| x.1 == "destroyed") { if t - x.0 > 12_000_000 { show("destroyed+12s", &tree(c.id())); d1 = true; } } } if !d2 { if let Some(x) = l.iter().find(|x| x.1 == "idle_after_cycles") { if t - x.0 > 12_000_000 { show("after8cycles+12s", &tree(c.id())); d2 = true; } } } }
        sleep(Duration::from_millis(1)); }
    note("tray"); let mut re: Vec<f64> = lines("tray").iter().filter(|x| x.1 == "reopen_start").filter_map(|x| vis.iter().find(|v| **v > x.0).map(|v| (*v - x.0) as f64 / 1e3)).collect(); println!("reopen raw={:?}", re.iter().map(|x| x.round()).collect::<Vec<_>>()); println!("reopen n={} median={:.0} max={:.0}", re.len(), pct(&mut re, 0.5), pct(&mut re, 1.0)); }
